<?php
function receipt_line_digest($r){$data=[];foreach(['id','batch_id','line_no','raw_item','product_id','source_qty','source_uom','conversion_factor','final_qty','validation_status','validation_message'] as $key)$data[$key]=$r[$key]??null;return hash('sha256',json_encode($data));}
function remove_extracted_receipt_line($batchId,$lineId,$digest,$reason){return remove_extracted_receipt_lines($batchId,[(int)$lineId=>$digest],$reason);}
function receipt_remove_selection($values,$expected){
 if(!is_array($values)||!$values||count($values)>5000)throw new Exception('Select 1 to 5000 receipt lines.');
 if(!is_scalar($expected)||!ctype_digit((string)$expected)||(int)$expected!==count($values))throw new Exception('The selected-line list was incomplete. Refresh and select the lines again.');
 $selected=[];foreach($values as $value){if(!is_string($value)||!preg_match('/^([1-9][0-9]*):([a-f0-9]{64})$/D',$value,$m)||isset($selected[(int)$m[1]]))throw new Exception('Invalid or repeated receipt line selection.');$selected[(int)$m[1]]=$m[2];}return $selected;
}
function remove_extracted_receipt_lines($batchId,$selected,$reason){
 if(!can_action('remove_receipt_lines'))throw new Exception('Receipt correction access required.');$reason=process_reason($reason);
 if(!is_array($selected)||!$selected||count($selected)>5000)throw new Exception('Select 1 to 5000 receipt lines.');
 foreach($selected as $id=>$digest)if(!is_int($id)||$id<1||!is_string($digest)||!preg_match('/^[a-f0-9]{64}$/D',$digest))throw new Exception('Invalid receipt line selection.');
 return process_transaction(function()use($batchId,$selected,$reason){
  $q=db()->prepare('SELECT * FROM inflow_batches WHERE id=? FOR UPDATE');$q->execute([(int)$batchId]);$b=$q->fetch();
  if(!$b||$b['batch_type']!=='Receipt PDF'||$b['status']!=='To Review')throw new Exception('Only an unconfirmed receipt can have extracted lines removed. Posted or closed records cannot be changed.');
  $q=db()->prepare('SELECT COUNT(*) FROM inflows WHERE batch_id=?');$q->execute([$b['id']]);if($q->fetchColumn())throw new Exception('This receipt already has posted stock. Use the approved correction process.');
  $ids=array_keys($selected);$marks=implode(',',array_fill(0,count($ids),'?'));$params=array_merge([$b['id']],$ids);
  $q=db()->prepare('SELECT * FROM receipt_staging_lines WHERE batch_id=? AND id IN ('.$marks.') ORDER BY line_no FOR UPDATE');$q->execute($params);$lines=$q->fetchAll();
  if(count($lines)!==count($selected))throw new Exception('A selected line changed, was removed or belongs to another receipt. Refresh the review.');
  // Validate the complete selection before changing any row, including stale requests.
  foreach($lines as $line)if(!hash_equals(receipt_line_digest($line),$selected[(int)$line['id']]))throw new Exception('A selected line changed. Refresh the review; no lines were removed.');
  $meta=json_decode($b['result_json']??'[]',true)?:[];if(!isset($meta['receipt_original_errors']))$meta['receipt_original_errors']=json_decode($b['error_json']??'[]',true)?:[];
  $group=bin2hex(random_bytes(12));$at=date('Y-m-d H:i:s');foreach($lines as $line)$meta['removed_receipt_lines'][]=['line'=>$line,'reason'=>$reason,'removed_by'=>current_user()['id'],'removed_name'=>current_user()['name'],'removed_at'=>$at,'physical_delta'=>0,'removal_group'=>$group];
  unset($meta['incoming_allocation']);db()->prepare('DELETE FROM receipt_staging_lines WHERE batch_id=? AND id IN ('.$marks.')')->execute($params);
  $q=db()->prepare('SELECT line_no,validation_status,validation_message FROM receipt_staging_lines WHERE batch_id=? ORDER BY line_no');$q->execute([$b['id']]);$remaining=$q->fetchAll();$errors=[];
  foreach($remaining as $row)if($row['validation_status']!=='Matched')$errors[]='Line '.$row['line_no'].': '.($row['validation_message']?:$row['validation_status']);
  if(!$remaining)$errors[]='No active receipt lines remain. Cancel the upload or upload a corrected original file.';
  db()->prepare('UPDATE inflow_batches SET result_json=?,error_count=?,error_json=? WHERE id=?')->execute([json_encode($meta),count($errors),json_encode($errors),$b['id']]);
  audit(count($lines)===1?'Remove extracted receipt line':'Remove extracted receipt lines','Inflow Batch',$b['batch_ref'],json_encode(['line_ids'=>$ids,'line_numbers'=>array_column($lines,'line_no'),'reason'=>$reason,'physical_delta'=>0,'allocation_review_required'=>true,'removal_group'=>$group]));return (int)$b['id'];
 });
}
function receipt_bulk_remove_toolbar($b){
 if($b['status']!=='To Review'||!can_action('remove_receipt_lines'))return;
 echo '<form id="receiptBulkRemove" method="post" action="actions.php" class="receipt-bulk-controls" data-confirm="Remove the selected receipt lines? They will not be posted; original lines and reason remain in history.">';workflow_hidden('remove_receipt_lines',['batch_id'=>$b['id'],'selection_count'=>0,'return'=>'receipt_review&id='.$b['id']]);
 echo '<div class="receipt-bulk-selection"><label class="receipt-bulk-select"><input type="checkbox" data-rl-select-all> Select All</label><span class="muted small" data-rl-selected-count aria-live="polite">0 selected</span></div><label class="receipt-bulk-reason">Shared reason<input name="reason" minlength="3" maxlength="2000" placeholder="Duplicate / incorrectly read lines" required></label><span class="receipt-bulk-submit"><button type="submit" class="btn danger sm" data-rl-remove-selected disabled>Remove Selected Lines</button></span></form><script src="assets/receipt_line_bulk.js?v=5.9.47" defer></script>';
}
function receipt_bulk_line_checkbox($b,$r){if($b['status']!=='To Review'||!can_action('remove_receipt_lines'))return '';return '<input type="checkbox" form="receiptBulkRemove" name="selected_lines[]" value="'.(int)$r['id'].':'.receipt_line_digest($r).'" data-rl-select aria-label="Select extracted line '.(int)$r['line_no'].'"> ';}
function receipt_remove_line_form($b,$r){
 if($b['status']!=='To Review'||!can_action('remove_receipt_line'))return;
 echo '<details style="margin-top:8px"><summary class="btn ghost sm">Remove Line</summary><form method="post" action="actions.php" class="stack" style="margin-top:8px" data-confirm="Remove this extracted line from the receipt? It will not be posted. The original line and reason will remain in history.">';
 workflow_hidden('remove_receipt_line',['batch_id'=>$b['id'],'line_id'=>$r['id'],'line_digest'=>receipt_line_digest($r),'return'=>'receipt_review&id='.$b['id']]);
 echo '<label>Reason<input name="reason" minlength="3" maxlength="2000" placeholder="Duplicate / not actually received" required></label><button class="btn danger sm">Remove This Line</button></form></details>';
}
function receipt_removed_history($b){
 receipt_added_history($b);
 $meta=json_decode($b['result_json']??'[]',true)?:[];$removed=$meta['removed_receipt_lines']??[];if(!$removed)return;
 echo '<div class="card table-wrap"><details><summary><b>Removed Receipt Lines · '.count($removed).'</b></summary><p class="muted small">Excluded from this inflow. Original PDF and extraction are retained. No stock was posted by removal. Review platform allocation again before confirmation.</p><table class="table"><tr><th>Original Line</th><th>Receipt Item</th><th>Excluded Qty</th><th>Reason</th><th>Removed By / Date</th></tr>';
 foreach($removed as $entry){$r=$entry['line'];echo '<tr><td>'.(int)$r['line_no'].'</td><td>'.e($r['raw_item']).'</td><td>'.e($r['final_qty']===null?'Unvalidated':number_format((int)$r['final_qty']).' pcs').'</td><td>'.e($entry['reason']).'</td><td>'.e($entry['removed_name']).'<br>'.e($entry['removed_at']).'</td></tr>';}
 echo '</table></details></div>';
}

function receipt_add_line($batchId,$input){
 if(!can_action('add_receipt_line'))throw new Exception('Receipt correction access required.');$reason=process_reason($input['reason']??'');$token=$input['request_key']??'';if(!is_string($token)||!preg_match('/^[a-f0-9]{32}$/D',$token))throw new Exception('Refresh the receipt before adding a line.');
 return process_transaction(function()use($batchId,$input,$reason,$token){
 $q=db()->prepare('SELECT * FROM inflow_batches WHERE id=? FOR UPDATE');$q->execute([(int)$batchId]);$b=$q->fetch();if(!$b||$b['batch_type']!=='Receipt PDF'||$b['status']!=='To Review')throw new Exception('Only an unconfirmed receipt can have lines added.');$q=db()->prepare('SELECT COUNT(*) FROM inflows WHERE batch_id=?');$q->execute([$b['id']]);if($q->fetchColumn())throw new Exception('This receipt already has posted stock.');
 $meta=json_decode($b['result_json']??'[]',true)?:[];foreach($meta['added_receipt_lines']??[] as $entry)if(($entry['request_key']??'')===$token)throw new Exception('This item line was already added. Refresh the review.');
 $after=(int)($input['after_line_id']??0);$pos=0;if($after){$q=db()->prepare('SELECT * FROM receipt_staging_lines WHERE batch_id=? AND id=? FOR UPDATE');$q->execute([$b['id'],$after]);$anchor=$q->fetch();if(!$anchor||!hash_equals(receipt_line_digest($anchor),(string)($input['after_digest']??'')))throw new Exception('Receipt lines changed. Refresh before inserting.');$pos=(int)$anchor['line_no'];}else{$q=db()->prepare('SELECT COUNT(*) FROM receipt_staging_lines WHERE batch_id=?');$q->execute([$b['id']]);if($q->fetchColumn())throw new Exception('Select the line after which to insert the missing item.');}
 $product=active_product((int)($input['product_id']??0));$raw=trim((string)($input['raw_item']??''));if($raw===''||strlen($raw)>1000)throw new Exception('Enter the missing description from the receipt (up to 1000 characters).');$source=receipt_numeric_value($input['source_qty']??'');$uom=trim((string)($input['source_uom']??'pc'));[$factor,$qty]=receipt_quantity($source,$uom);
 db()->prepare('UPDATE receipt_staging_lines SET line_no=line_no+1 WHERE batch_id=? AND line_no>? ORDER BY line_no DESC')->execute([$b['id'],$pos]);db()->prepare("INSERT INTO receipt_staging_lines(batch_id,line_no,raw_item,product_id,source_qty,source_uom,conversion_factor,final_qty,validation_status,validation_message) VALUES(?,?,?,?,?,?,?,?, 'Matched','Manually added from original receipt')")->execute([$b['id'],$pos+1,$raw,$product['id'],$source,$uom,$factor,$qty]);$newId=(int)db()->lastInsertId();
 $meta['added_receipt_lines'][]=['request_key'=>$token,'line_id'=>$newId,'inserted_after_id'=>$after,'line_no_at_add'=>$pos+1,'raw_item'=>$raw,'product_id'=>$product['id'],'sku'=>$product['master_sku'],'source_qty'=>$source,'source_uom'=>$uom,'final_qty'=>$qty,'reason'=>$reason,'added_by'=>current_user()['id'],'added_name'=>current_user()['name'],'added_at'=>date('Y-m-d H:i:s'),'physical_delta'=>0];unset($meta['incoming_allocation']);
 $q=db()->prepare("SELECT line_no,validation_status,validation_message FROM receipt_staging_lines WHERE batch_id=? AND validation_status<>'Matched' ORDER BY line_no");$q->execute([$b['id']]);$errors=[];foreach($q as $row)$errors[]='Line '.$row['line_no'].': '.$row['validation_message'];db()->prepare('UPDATE inflow_batches SET result_json=?,error_count=?,error_json=? WHERE id=?')->execute([json_encode($meta),count($errors),json_encode($errors),$b['id']]);audit('Add missing receipt line','Inflow Batch',$b['batch_ref'],json_encode(end($meta['added_receipt_lines'])));return (int)$b['id'];
 });
}
function receipt_add_line_form($b,$r=null){if($b['status']!=='To Review'||!can_action('add_receipt_line'))return;echo '<details class="receipt-add-line" style="margin-top:8px"><summary class="btn ghost sm">'.($r?'＋ Add Item After This Line':'＋ Add Missing Item').'</summary><form method="post" action="actions.php" class="stack" style="margin-top:10px" data-confirm="Add this missing item from the original receipt? No stock changes until final confirmation.">';workflow_hidden('add_receipt_line',['batch_id'=>$b['id'],'after_line_id'=>$r['id']??0,'after_digest'=>$r?receipt_line_digest($r):'','request_key'=>bin2hex(random_bytes(16)),'return'=>'receipt_review&id='.$b['id']]);echo '<label>Receipt item description<input name="raw_item" maxlength="1000" required></label><label>Product / SKU</label>'.picker('product_id','Select the missing product...',true,'',false).'<div class="row"><label>Shipped quantity<input name="source_qty" inputmode="decimal" placeholder="27" required></label><label>UOM<input name="source_uom" value="pc" required></label></div><label>Reason<input name="reason" minlength="3" maxlength="2000" placeholder="Item not extracted from original PDF" required></label><button class="btn secondary">Add &amp; Validate Item</button></form></details>';}
function receipt_added_history($b){$m=json_decode($b['result_json']??'[]',true)?:[];if(empty($m['added_receipt_lines']))return;echo '<div class="card table-wrap"><details><summary><b>Manually Added Receipt Lines · '.count($m['added_receipt_lines']).'</b></summary><p class="muted small">Original extraction retained. Adding a review line does not post stock. Removed lines remain excluded.</p><table class="table"><tr><th>Item / SKU</th><th>Added Qty</th><th>Reason</th><th>Added By / Date</th></tr>';foreach($m['added_receipt_lines'] as $a)echo '<tr><td>'.e($a['raw_item']).'<br>'.e($a['sku']).'</td><td>'.(int)$a['final_qty'].' pcs</td><td>'.e($a['reason']).'</td><td>'.e($a['added_name']).'<br>'.e($a['added_at']).'</td></tr>';echo '</table></details></div>';}
function receipt_line_action_assets(){static $done=false;if($done)return;$done=true;echo '<link rel="stylesheet" href="assets/receipt_line_actions.css?v=5.9.50"><script src="assets/receipt_line_actions.js?v=5.9.50" defer></script>';}
function receipt_line_actions($b,$r=null){
 if($b['status']!=='To Review')return;
 $allowed=[];if($r&&can_action('resolve_receipt_line'))$allowed['edit']='Edit / Validate Line';if(can_action('add_receipt_line'))$allowed['add']=$r?'Add Item After This Line':'Add Missing Item';if($r&&can_action('remove_receipt_line'))$allowed['remove']='Remove Line';if(!$allowed){echo '<span class="muted small">View only</span>';return;}
 $key='receipt-action-'.(int)$b['id'].'-'.(int)($r['id']??0);echo '<div class="receipt-line-actions"><button type="button" class="btn ghost sm" data-receipt-menu="'.$key.'-menu" aria-controls="'.$key.'-menu" aria-haspopup="menu" aria-expanded="false">Actions <span aria-hidden="true">⌄</span></button><div id="'.$key.'-menu" class="receipt-line-action-menu" popover="auto" role="menu" aria-label="Receipt line actions" hidden>';
 foreach($allowed as $kind=>$label)echo '<button type="button" role="menuitem" data-receipt-dialog="'.$key.'-'.$kind.'"'.($kind==='remove'?' class="receipt-action-remove"':'').'>'.e($label).'</button>';echo '</div>';
 foreach($allowed as $kind=>$label){echo '<dialog id="'.$key.'-'.$kind.'" class="receipt-line-dialog" aria-labelledby="'.$key.'-'.$kind.'-title"><div class="receipt-dialog-head"><h3 id="'.$key.'-'.$kind.'-title">'.e($label).'</h3><button type="button" class="icon-btn" data-receipt-close aria-label="Close popup">×</button></div><div class="receipt-dialog-body"><p class="muted small">'.($r?'Line '.(int)$r['line_no'].' · '.e($r['raw_item']):'Add the missing item from the original receipt.').'</p>';
 if($kind==='edit'){
 echo '<form method="post" action="actions.php" class="stack receipt-correction" data-confirm="Validate this corrected product, shipped quantity and UOM? No stock will be posted.">';workflow_hidden('resolve_receipt_line',['line_id'=>$r['id'],'return'=>'receipt_review&id='.$b['id']]);echo '<label>Product / SKU</label>'.picker('product_id','Select correct product...',true,$r['product_id']??'',false).'<div class="row"><label>Shipped quantity<input name="source_qty" type="number" min="0.01" step="0.01" value="'.e($r['source_qty']).'" required></label><label>UOM<input name="source_uom" value="'.e($r['source_uom']).'" placeholder="pc or bx(12)" required></label></div><label class="ack"><input type="checkbox" name="save_alias" value="1"> Save this description as an alias</label><p class="muted small">Validation does not post stock. Review platform allocation before final confirmation.</p><div class="modal-actions"><button type="button" class="btn ghost" data-receipt-close>Cancel</button><button class="btn primary">Validate Correction</button></div></form>';
 }else{
 // Reuse the existing action forms, including CSRF, fingerprints and request keys.
 ob_start();if($kind==='add')receipt_add_line_form($b,$r);else receipt_remove_line_form($b,$r);$html=ob_get_clean();if(preg_match('~<form\b.*?</form>~s',$html,$match))echo $match[0];
 echo '<div class="receipt-dialog-cancel"><button type="button" class="btn ghost" data-receipt-close>Cancel</button></div>';
 }
 echo '</div></dialog>';}
 echo '</div>';
}
